import type { DifficultyTag, ExperimentSplit, LanguageId, ModelId, TrainingSize } from "./types";

/**
 * ILLUSTRATIVE EXPERIMENT VALUES
 * ------------------------------
 * These numbers are NOT measured. They are generated by a deterministic formula so the
 * interface can demonstrate the expected *shape* of a lemma-disjoint result.
 * Replace `getResult` with a lookup into real evaluation output (see README).
 */
export const ILLUSTRATIVE = true;

export const trainingSizes: TrainingSize[] = [50, 100, 250, 500];

export const models: Record<ModelId, { name: string; detail: string }> = {
  baseline: { name: "Baseline", detail: "Multilingual encoder · surface forms only" },
  morph: { name: "Morphology-aware", detail: "Encoder + explicit morphological features" },
};

export const task = {
  name: "Inflected-form prediction",
  description: "Given a lemma and a target feature bundle, predict the inflected surface form.",
  metric: "Exact-match accuracy (%)",
};

/** Anchor values at 500 training examples (Turkish), taken from the design brief. */
const anchors: Record<ExperimentSplit, Record<ModelId, number>> = {
  random: { baseline: 91.4, morph: 93.1 },
  "lemma-disjoint": { baseline: 62.7, morph: 76.8 },
};

/** Points lost per halving of training data. */
const decay: Record<ExperimentSplit, Record<ModelId, number>> = {
  random: { baseline: 3.2, morph: 2.6 },
  "lemma-disjoint": { baseline: 5.5, morph: 4.2 },
};

/** Illustrative per-language offsets (random, lemma-disjoint). */
const languageOffset: Record<LanguageId, [number, number]> = {
  tur: [0, 0],
  urd: [-2.4, -3.6],
  evn: [-5.1, -7.9],
  ckt: [-6.8, -10.2],
};

export function getResult(lang: LanguageId, split: ExperimentSplit, size: TrainingSize, model: ModelId): number {
  const halvings = Math.log2(500 / size);
  const [rOff, lOff] = languageOffset[lang];
  const offset = split === "random" ? rOff : lOff * (model === "morph" ? 0.75 : 1);
  const value = anchors[split][model] - decay[split][model] * halvings + offset;
  return Math.round(value * 10) / 10;
}

export type PredictionScenario = {
  languageId: LanguageId;
  train: { lemma: string; forms: string[] }[];
  test: { lemma: string; features: string; gold: string };
  baseline: { prediction: string; verdict: string };
  morph: { prediction: string; verdict: string };
  explanation: string;
  difficulty: DifficultyTag[];
};

